css:
.cohortsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a2336;
    background: linear-gradient(160deg, #f6f1e9 0%, #efe7f1 100%);
    border-radius: 18px;
}

.cohortsim-container * {
    box-sizing: border-box;
}

.cohortsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2b1b4d 0%, #432a73 55%, #6d4aa0 100%);
    color: #faf7ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(43, 27, 77, 0.32);
}

.cohortsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.cohortsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #e8d49a;
    background: rgba(255, 255, 255, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.cohortsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #ece4f6;
}

.cohortsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a3a6b;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cohortsim-period-counter #currentDay,
.cohortsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2b1b4d;
}

.cohortsim-round-name {
    background: #e3d7f0;
    color: #2b1b4d;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cohortsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: #f6e8c8;
    padding: 4px 12px;
    border-radius: 999px;
}

.cohortsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cohortsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3dced;
    box-shadow: 0 4px 14px rgba(43, 27, 77, 0.06);
    border-top: 4px solid #6d4aa0;
}

.cohortsim-card-fit { border-top-color: #2f6fb0; }
.cohortsim-card-sat { border-top-color: #b07a16; }
.cohortsim-card-margin { border-top-color: #1f8a5b; }
.cohortsim-card-faculty { border-top-color: #6d4aa0; }

.cohortsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a6c8f;
}

.cohortsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2b1b4d;
}

.cohortsim-card-fit .cohortsim-value { color: #2f6fb0; }
.cohortsim-card-sat .cohortsim-value { color: #b07a16; }
.cohortsim-card-margin .cohortsim-value { color: #1f8a5b; }
.cohortsim-card-faculty .cohortsim-value { color: #6d4aa0; }

.cohortsim-sublabel {
    font-size: 0.76rem;
    color: #8c7ea0;
    line-height: 1.35;
}

.cohortsim-sat-fail .cohortsim-value { color: #c0392b; }
.cohortsim-sat-pass .cohortsim-value { color: #1f8a5b; }

.cohortsim-margin-fail .cohortsim-value { color: #c0392b; }
.cohortsim-margin-pass .cohortsim-value { color: #1f8a5b; }

.cohortsim-faculty-over { border-top-color: #c0392b; }
.cohortsim-faculty-over .cohortsim-value { color: #c0392b; }

.cohortsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2b1b4d;
    color: #f3ecfb;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cohortsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.cohortsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #6d4aa0;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(43, 27, 77, 0.05);
}

.cohortsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cohortsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2b1b4d;
    margin-bottom: 6px;
}

.cohortsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #463a5c;
}

.cohortsim-briefing-text strong { color: #1f8a5b; }
.cohortsim-briefing-text em { color: #8a5a12; font-style: italic; }

.cohortsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3dced;
    box-shadow: 0 4px 14px rgba(43, 27, 77, 0.06);
}

.cohortsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2b1b4d;
    border-bottom: 2px solid #efe7f4;
    padding-bottom: 8px;
}

.cohortsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a2d54;
    margin: 14px 0 6px;
}

.cohortsim-container select,
.cohortsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdbfdf;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #faf7fd;
    color: #2a2336;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cohortsim-container select:focus,
.cohortsim-container input[type="number"]:focus {
    outline: none;
    border-color: #6d4aa0;
    box-shadow: 0 0 0 3px rgba(109, 74, 160, 0.16);
}

.cohortsim-container select option {
    background-color: #ffffff;
    color: #2a2336;
}

.cohortsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6d4aa0;
}

.cohortsim-range-readout,
.cohortsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a4585;
    margin-top: 4px;
}

.cohortsim-range-readout span:last-child {
    color: #1f8a5b;
    font-weight: 800;
}

.cohortsim-hint {
    font-size: 0.8rem;
    color: #8c7ea0;
    margin-top: 8px;
    line-height: 1.4;
}

.cohortsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.cohortsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f2fb;
    border: 1px solid #e5dcf0;
    border-radius: 9px;
    padding: 8px 12px;
}

.cohortsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3a2d54;
}

.cohortsim-alloc-row select {
    width: 180px;
    flex: 0 0 180px;
}

.cohortsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cohortsim-container .btn-primary {
    background: linear-gradient(135deg, #6d4aa0 0%, #432a73 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(67, 42, 115, 0.30);
}

.cohortsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.cohortsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdbfdf;
    color: #7a6c8f;
}

.cohortsim-coach {
    background: #2b1b4d;
    color: #f3ecfb;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(43, 27, 77, 0.24);
}

.cohortsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #c5a4ec;
    margin-bottom: 8px;
}

.cohortsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cohortsim-coach-body strong { color: #f2d98a; }
.cohortsim-coach-body em { color: #f5c9a8; font-style: italic; }

.cohortsim-history,
.cohortsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3dced;
    box-shadow: 0 4px 14px rgba(43, 27, 77, 0.06);
}

.cohortsim-history h3,
.cohortsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2b1b4d;
}

.cohortsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a2d54;
}

.cohortsim-container table#usfHistoryTable th {
    background: #f1ebf7;
    color: #2b1b4d;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d6f0;
}

.cohortsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0eaf6;
}

.cohortsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7fd;
}

.cohortsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cohortsim-container {
        padding: 14px;
    }
    .cohortsim-header h1 {
        font-size: 1.7rem;
    }
    .cohortsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cohortsim-value {
        font-size: 2rem;
    }
    .cohortsim-clock {
        margin-left: 0;
    }
    .cohortsim-period-counter {
        font-size: 0.88rem;
    }
    .cohortsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cohortsim-alloc-row {
        flex-wrap: wrap;
    }
    .cohortsim-alloc-row select {
        width: 100%;
        flex: 1 1 100%;
    }
    .cohortsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ===== v1.1.0 completion message — append-only ===== */
.cohort-cm{background:#ffffff;border:1px solid #e2dcea;border-radius:12px;padding:22px 24px;margin:18px 0;color:#241c33;font-family:inherit;box-shadow:0 2px 10px rgba(30,20,50,0.06);}
.cohort-cm-head{text-align:center;border-bottom:1px solid #efeaf4;padding-bottom:14px;margin-bottom:14px;}
.cohort-cm-title{font-size:15px;font-weight:600;letter-spacing:.02em;color:#7a4fa0;text-transform:uppercase;}
.cohort-cm-scorewrap{margin:8px 0 2px;}
.cohort-cm-score{font-size:52px;font-weight:800;color:#7a4fa0;line-height:1;}
.cohort-cm-score-max{font-size:20px;font-weight:600;color:#9a93a6;margin-left:2px;}
.cohort-cm-grade{font-size:18px;font-weight:700;color:#241c33;margin-top:4px;}
.cohort-cm-badges{margin-top:10px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap;}
.cohort-cm-badge{display:inline-block;padding:4px 12px;border-radius:999px;font-size:12px;font-weight:700;letter-spacing:.02em;}
.cohort-cm-met{background:#eee7f6;color:#7a4fa0;border:1px solid #d8c7ea;}
.cohort-cm-fail{background:#fdecec;color:#b3261e;border:1px solid #f4c7c3;}
.cohort-cm-metrics{display:flex;gap:10px;justify-content:space-between;flex-wrap:wrap;margin:6px 0 14px;}
.cohort-cm-metric{flex:1 1 0;min-width:70px;text-align:center;background:#f8f5fc;border:1px solid #ece4f4;border-radius:9px;padding:10px 6px;}
.cohort-cm-metric-val{font-size:22px;font-weight:800;color:#7a4fa0;}
.cohort-cm-metric-lbl{font-size:11px;color:#5a5568;margin-top:2px;text-transform:uppercase;letter-spacing:.02em;}
.cohort-cm-insights{background:#faf9fc;border:1px solid #efecf4;border-radius:9px;padding:12px 16px;}
.cohort-cm-insights-title{font-size:13px;font-weight:700;color:#7a4fa0;margin-bottom:6px;text-transform:uppercase;letter-spacing:.02em;}
.cohort-cm-insights ul{margin:0;padding-left:18px;}
.cohort-cm-insights li{font-size:13.5px;line-height:1.5;color:#2f2840;margin-bottom:6px;}

