(function() {
    'use strict';

    class CohortAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Global Cohort`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.FEE_K = 1400;            // EUR 1.4M flat fee, in EUR thousands
            this.START_MARGIN = 30;       // standardized program starts high-margin (30%)
            this.MARGIN_TARGET = 22;      // 22% contribution-margin floor (EUR 308K)
            this.MARGIN_POOL_K = 308;     // EUR 308K = the 22% floor, in EUR thousands
            this.SAT_BAR = 4.2;           // contractual module-1 satisfaction bar, per market
            this.FORFEIT_PTS = 10;        // 10% of fee (EUR 140K) forfeited if any market misses the bar
            this.TRIP_K = 4.8;            // EUR 4,800 per core-faculty fly-in trip
            this.CORE_CAP = 2;            // two core faculty -> at most 2 markets staffed by core at once
            this.START_FIT = 30;          // starting cross-cultural fit per market
            this.GUARANTEED_SEATS = 75;   // of 90; final 15 are pilot-dependent
            this.FULL_SEATS = 90;

            // 1 margin point = 1% of the EUR 1.4M fee = EUR 14K. Spending erodes margin from 30% toward
            // the 22% floor: the spendable headroom before breaching the floor is (30-22)% = EUR 112K.
            this.K_PER_POINT = this.FEE_K / 100; // 14 EUR-K per margin point
        }

        // Fit (0-100) -> satisfaction on a 5.0 scale. fit 30 -> ~3.24, fit 69 -> ~4.19, fit 100 -> 5.0.
        // A market needs roughly fit >= 69 to clear the 4.2 bar.
        _fitToSat(fit) {
            return Math.min(5, Math.round((2.5 + (Math.max(0, Math.min(100, fit)) / 100) * 2.45) * 100) / 100);
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                const f = this.START_FIT;
                state.domainState = {
                    fitFr: f, fitDe: f, fitUae: f,
                    fitAvg: f,
                    satWeakest: this._fitToSat(f),
                    marginPct: this.START_MARGIN,
                    marginSpent: 0,
                    coreMarkets: 0,
                    enrolment: this.GUARANTEED_SEATS,
                    barMissed: false,
                    forfeited: false,
                    fitHistory: [f],
                    satHistory: [Math.round(this._fitToSat(f) * 20)],
                    marginHistory: [this.START_MARGIN],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING / neutral mix — never the textbook-correct play.
                state.decisions = {
                    split: `core`,
                    lens: `single`,
                    risk: `deabstract`,
                    rigour: 50,
                    modeFr: `inperson`,
                    modeDe: `blended`,
                    modeUae: `blended`,
                    adaptFr: `light`,
                    adaptDe: `moderate`,
                    adaptUae: `moderate`,
                    facFr: `core`,
                    facDe: `coteach`,
                    facUae: `coteach`,
                    consistency: `materials`,
                    contingency: 40,
                    diag: `language`,
                    fix: `nudge`,
                    pitch: `margin`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const get = (id) => document.getElementById(id);

            if (round === 1) {
                const sp = get(`splitInput`), ln = get(`lensInput`), rk = get(`riskInput`), rg = get(`rigourInput`);
                if (sp) decisions.split = sp.value;
                if (ln) decisions.lens = ln.value;
                if (rk) decisions.risk = rk.value;
                if (rg) decisions.rigour = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const mf = get(`modeFrInput`), md = get(`modeDeInput`), mu = get(`modeUaeInput`);
                const af = get(`adaptFrInput`), ad = get(`adaptDeInput`), au = get(`adaptUaeInput`);
                if (mf) decisions.modeFr = mf.value;
                if (md) decisions.modeDe = md.value;
                if (mu) decisions.modeUae = mu.value;
                if (af) decisions.adaptFr = af.value;
                if (ad) decisions.adaptDe = ad.value;
                if (au) decisions.adaptUae = au.value;
                const valid = [`inperson`, `blended`, `virtual`];
                if (![decisions.modeFr, decisions.modeDe, decisions.modeUae].every((v) => valid.includes(v))) {
                    warn(`warn_mode_invalid`); return false;
                }
            } else if (round === 3) {
                const ff = get(`facFrInput`), fd = get(`facDeInput`), fu = get(`facUaeInput`);
                const cs = get(`consistencyInput`), cg = get(`contingencyInput`);
                if (ff) decisions.facFr = ff.value;
                if (fd) decisions.facDe = fd.value;
                if (fu) decisions.facUae = fu.value;
                if (cs) decisions.consistency = cs.value;
                if (cg) decisions.contingency = parseInt(cg.value, 10);
                if (!Number.isFinite(decisions.contingency) || decisions.contingency < 0 || decisions.contingency > 100) {
                    warn(`warn_contingency_range`); return false;
                }
            } else if (round === 4) {
                const dg = get(`diagInput`), fx = get(`fixInput`), pt = get(`pitchInput`), cv = get(`convictionInput`);
                if (dg) decisions.diag = dg.value;
                if (fx) decisions.fix = fx.value;
                if (pt) decisions.pitch = pt.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Per-market fit deltas, margin spend (EUR-K), core-faculty market commitments, coach + summary keys.
            let dFr = 0, dDe = 0, dUae = 0;
            let spend = 0, coreMarkets = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Separate durable core from culture-bound surface (Key Concept / Common Error 5).
                switch (d.split) {
                    case `surface`: dFr += 8; dDe += 11; dUae += 13; coachKey = `coach_r1_surface`; break;
                    case `core`:    dFr -= 4; dDe -= 6;  dUae -= 6;  coachKey = `coach_r1_core`; break;     // localizes wrong layer
                    case `all`:     dFr += 4; dDe += 5;  dUae += 5;  coachKey = `coach_r1_all`; break;       // gold-plating instinct
                    case `none`:    dFr += 3; dDe -= 8;  dUae -= 12; coachKey = `coach_r1_none`; break;      // standardize-everything
                }

                // Per-market vs one-international-version (Common Error 5).
                switch (d.lens) {
                    case `permarket`: dDe += 9; dUae += 11; if (d.split === `surface`) coachKey = `coach_r1_sharp`; break;
                    case `single`:    dDe -= 4; dUae -= 6;  coachKey = (coachKey === `coach_default`) ? `coach_r1_single` : coachKey; break;
                    case `french`:    dDe -= 8; dUae -= 12; coachKey = `coach_r1_french`; break;
                }

                // Highest-risk flag: the UAE direct-feedback role-play is the true top risk.
                switch (d.risk) {
                    case `uaefeedback`: dUae += 8; break;
                    case `deabstract`:  dDe += 4; dUae -= 2; break;   // a real DE risk, but UAE is the bigger one
                    case `language`:    dUae -= 6; coachKey = `coach_r1_language`; break;
                    case `norisk`:      dFr -= 4; dDe -= 6; dUae -= 8; coachKey = `coach_r1_norisk`; break;
                }

                // Diagnostic rigour amplifies a correct split, does little for a wrong one.
                const rigourGain = Math.round((d.rigour - 50) / 10);
                if (d.split === `surface`) { dFr += rigourGain; dDe += rigourGain; dUae += rigourGain; }
                else if (d.rigour <= 25) { coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.split === `surface` && d.lens === `permarket` && d.risk === `uaefeedback`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Delivery mode per market. In-person lifts fit + cost; virtual protects margin but
                // caps relationship-building (a real risk in the UAE cohort).
                const modeEffect = (mode, market) => {
                    // returns [fitDelta, spendK]
                    if (mode === `inperson`) {
                        // UAE most needs presence; FR cheap at home; DE moderate.
                        if (market === `uae`) return [16, 16];
                        if (market === `de`) return [11, 11];
                        return [9, 5]; // FR home turf
                    } else if (mode === `blended`) {
                        if (market === `uae`) return [8, 8];
                        if (market === `de`) return [9, 6];
                        return [7, 3];
                    } else { // virtual
                        if (market === `uae`) return [-6, 2];   // relationship-building collapses
                        if (market === `de`) return [4, 2];     // DE tolerates structured virtual
                        return [4, 2];
                    }
                };
                const [fF, sF] = modeEffect(d.modeFr, `fr`);
                const [fD, sD] = modeEffect(d.modeDe, `de`);
                const [fU, sU] = modeEffect(d.modeUae, `uae`);
                dFr += fF; dDe += fD; dUae += fU;
                spend += sF + sD + sU;

                // Cultural-adaptation level per market. Deep spend pays off where risk is high (UAE,
                // then DE); deep spend in FR is gold-plating the easy market (Common Error 2).
                const adaptEffect = (lvl, market) => {
                    const costMap = { light: 4, moderate: 12, deep: 24 };
                    let fit = 0;
                    if (market === `uae`) fit = { light: 2, moderate: 13, deep: 19 }[lvl];
                    else if (market === `de`) fit = { light: 3, moderate: 12, deep: 15 }[lvl];
                    else fit = { light: 7, moderate: 8, deep: 9 }[lvl]; // FR already fits — diminishing returns
                    return [fit, costMap[lvl]];
                };
                const [aF, acF] = adaptEffect(d.adaptFr, `fr`);
                const [aD, acD] = adaptEffect(d.adaptDe, `de`);
                const [aU, acU] = adaptEffect(d.adaptUae, `uae`);
                dFr += aF; dDe += aD; dUae += aU;
                spend += acF + acD + acU;

                const goldPlatedFr = (d.adaptFr === `deep`);
                const underUae = (d.adaptUae === `light`);
                if (goldPlatedFr && underUae) coachKey = `coach_r2_misallocated`;
                else if (d.modeUae === `virtual`) coachKey = `coach_r2_uaevirtual`;
                else if (d.adaptUae === `deep` && d.adaptFr !== `deep`) coachKey = `coach_r2_smart`;
                else if (goldPlatedFr) coachKey = `coach_r2_goldplate`;
                else coachKey = `coach_r2_default`;

                summaryKey = (d.adaptUae !== `light` && d.modeUae !== `virtual` && !goldPlatedFr) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Faculty mix under scarcity. Local-on-price-alone risks the 4.2 bar (Common Error 4);
                // fly-in everywhere drains the two-faculty capacity (Common Error 3).
                const tk2 = this.TRIP_K * 2; // a module week needs the core faculty on site repeatedly
                const facEffect = (model, market) => {
                    // returns [fitDelta, spendK, coreMarket(0/1)] — coreMarket flags a market staffed by
                    // one of the two scarce core faculty that same week.
                    if (market === `fr`) {
                        if (model === `core`) return [9, 0, 1];
                        if (model === `coteach`) return [10, 8, 1];
                        return [-2, 3, 0]; // local adjunct in FR — needless quality risk
                    }
                    if (market === `de`) {
                        if (model === `coteach`) return [15, 8 + tk2, 1];   // fly-in core + German affiliate
                        if (model === `affiliate`) return [12, 5, 0];        // certified affiliate frees a core slot
                        if (model === `flyin`) return [11, tk2, 1];          // core alone
                        return [-4, 3, 0];                                   // unvetted local
                    }
                    // uae
                    if (model === `coteach`) return [17, 10 + tk2, 1]; // fly-in core + certified local
                    if (model === `flyin`) return [12, tk2, 1];        // core alone
                    return [-14, 3, 0];                                // unvetted local on price alone — the 3.9 risk
                };
                const [fF, sF, cF] = facEffect(d.facFr, `fr`);
                const [fD, sD, cD] = facEffect(d.facDe, `de`);
                const [fU, sU, cU] = facEffect(d.facUae, `uae`);
                dFr += fF; dDe += fD; dUae += fU;
                spend += sF + sD + sU;
                coreMarkets += cF + cD + cU;

                // Brand-consistency mechanism multiplies the value of local/affiliate/co-teach faculty.
                const usesLocal = [d.facFr, d.facDe, d.facUae].some((m) => m === `local` || m === `affiliate` || m === `coteach`);
                switch (d.consistency) {
                    case `full`: if (usesLocal) { dFr += 3; dDe += 5; dUae += 6; } spend += 4; coachKey = `coach_r3_consistency`; break;
                    case `materials`: dDe += 1; dUae += 1; break;
                    case `none`: if (usesLocal) { dDe -= 10; dUae -= 14; coachKey = `coach_r3_noconsistency`; } break;
                }

                // Contingency for the UAE adjunct underperforming (observation + backup).
                if (d.facUae === `local`) {
                    if (d.contingency >= 50) { dUae += 4; }
                    else { dUae -= 6; coachKey = `coach_r3_nocontingency`; }
                } else if (d.contingency >= 40) {
                    dUae += 2;
                }

                // Over-commit the two core faculty across simultaneous markets (Common Error 3):
                // staffing all three markets with core faculty needs 3 people, you have 2.
                if ((ds.coreMarkets + coreMarkets) > this.CORE_CAP) {
                    dFr -= 7; dDe -= 7; dUae -= 7;
                    coachKey = `coach_r3_overcommit`;
                } else if (d.facUae === `local` && d.consistency === `none`) {
                    coachKey = `coach_r3_uaecheap`;
                } else if (coachKey === `coach_default`) {
                    coachKey = `coach_r3_default`;
                }

                const uaeProtected = (d.facUae !== `local`) || d.contingency >= 50;
                summaryKey = (uaeProtected && (ds.coreMarkets + coreMarkets) <= this.CORE_CAP && d.consistency !== `none`) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Diagnose the UAE pilot miss (3.9) against the Round 1 risk flags (Common Error 4).
                switch (d.diag) {
                    case `feedback`: dUae += 6; coachKey = `coach_r4_diag`; break;
                    case `language`: dUae -= 4; coachKey = `coach_r4_language`; break;
                    case `cohort`:   dUae -= 8; coachKey = `coach_r4_cohort`; break;
                }

                // Targeted, costed UAE remediation. Swap = right-sized; rebuild = gold-plating that
                // breaks margin; nudge/nothing leave the bar breached.
                switch (d.fix) {
                    case `swap`:    dUae += 16; spend += 14; if (d.diag === `feedback`) coachKey = `coach_r4_swap`; break;
                    case `rebuild`: dUae += 18; spend += 60; coachKey = `coach_r4_rebuild`; break;
                    case `nudge`:   dUae += 1;  spend += 2;  coachKey = `coach_r4_nudge`; break;
                    case `nothing`: dUae -= 4;  spend += 0;  coachKey = `coach_r4_nothing`; break;
                }

                // The pitch frame.
                switch (d.pitch) {
                    case `disciplined`: dFr += 2; dDe += 2; dUae += 2; if (d.fix === `swap`) coachKey = `coach_r4_pitch`; break;
                    case `margin`:      dUae -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_pitchmargin` : coachKey; break;
                    case `premium`:     coachKey = (coachKey === `coach_default`) ? `coach_r4_pitchpremium` : coachKey; break;
                }

                // Conviction nudges fit modestly.
                const cv = Math.round((d.conviction - 60) / 12);
                dFr += cv; dDe += cv; dUae += cv;

                summaryKey = (d.diag === `feedback` && d.fix === `swap` && d.pitch === `disciplined`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply per-market fit, clamped 0-100.
            ds.fitFr = Math.max(0, Math.min(100, ds.fitFr + dFr));
            ds.fitDe = Math.max(0, Math.min(100, ds.fitDe + dDe));
            ds.fitUae = Math.max(0, Math.min(100, ds.fitUae + dUae));
            ds.fitAvg = Math.round((ds.fitFr + ds.fitDe + ds.fitUae) / 3);

            // Resource accounting. Margin erodes from the 30% start as localization spend consumes it.
            ds.marginSpent = Math.round(ds.marginSpent + spend);
            ds.coreMarkets = ds.coreMarkets + coreMarkets;
            ds.marginPct = Math.round((this.START_MARGIN - ds.marginSpent / this.K_PER_POINT) * 10) / 10;

            // Satisfaction outlook = the WEAKEST market (the bar must hold in EVERY market).
            const satFr = this._fitToSat(ds.fitFr);
            const satDe = this._fitToSat(ds.fitDe);
            const satUae = this._fitToSat(ds.fitUae);
            ds.satWeakest = Math.min(satFr, satDe, satUae);

            // Enrolment: the final 15 seats depend on a satisfactory pilot (avg fit health + the bar).
            if (ds.fitAvg >= 70 && ds.satWeakest >= this.SAT_BAR) ds.enrolment = this.FULL_SEATS;
            else if (ds.fitAvg >= 55) ds.enrolment = 84;
            else ds.enrolment = this.GUARANTEED_SEATS;

            // Final round: if any market misses the 4.2 bar, forfeit 10% of the fee (EUR 140K =
            // 10 margin points), which crashes the margin you were protecting.
            if (round === this.ROUNDS.length) {
                if (ds.satWeakest < this.SAT_BAR) {
                    ds.barMissed = true;
                    ds.forfeited = true;
                    ds.marginPct = Math.round((ds.marginPct - this.FORFEIT_PTS) * 10) / 10;
                }
            }

            ds.fitHistory.push(ds.fitAvg);
            ds.satHistory.push(Math.round(ds.satWeakest * 20)); // 5.0 scale -> 0-100 for the chart
            ds.marginHistory.push(ds.marginPct);

            // v1.1.0 fix: persist instructor-card composite every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                fitAvg: ds.fitAvg,
                fitFr: Math.round(ds.fitFr),
                fitDe: Math.round(ds.fitDe),
                fitUae: Math.round(ds.fitUae),
                satWeakest: ds.satWeakest,
                marginPct: ds.marginPct,
                marginSpent: ds.marginSpent,
                coreMarkets: ds.coreMarkets,
                enrolment: ds.enrolment,
                barMissed: ds.barMissed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`fitDisplay`, `domainState.fitAvg`, (v) => Math.round(Number(v)));

            uiManager.bind(`satDisplay`, `domainState.satWeakest`, (v) => {
                const card = document.querySelector(`.cohortsim-card-sat`);
                if (card) {
                    card.classList.toggle(`cohortsim-sat-pass`, Number(v) >= this.SAT_BAR);
                    card.classList.toggle(`cohortsim-sat-fail`, Number(v) < this.SAT_BAR);
                }
                return Number(v).toFixed(1);
            });

            uiManager.bind(`marginDisplay`, `domainState.marginPct`, (v) => {
                const card = document.querySelector(`.cohortsim-card-margin`);
                if (card) {
                    card.classList.toggle(`cohortsim-margin-pass`, Number(v) >= this.MARGIN_TARGET);
                    card.classList.toggle(`cohortsim-margin-fail`, Number(v) < this.MARGIN_TARGET);
                }
                return this._fmtPct(Number(v));
            });

            uiManager.bind(`facultyDisplay`, `domainState.coreMarkets`, (v) => {
                const card = document.querySelector(`.cohortsim-card-faculty`);
                if (card) card.classList.toggle(`cohortsim-faculty-over`, Number(v) > this.CORE_CAP);
                return Math.round(Number(v)) + ` / ` + this.CORE_CAP;
            });

            uiManager.bind(`budgetDisplay`, `domainState.marginSpent`, (v) => {
                return this._fmtMoneyK(Number(v)) + ` / ` + this._fmtMoneyK(this.MARGIN_POOL_K);
            });

            const self = this;

            // Rigour slider readout.
            const rg = document.getElementById(`rigourInput`);
            const rgReadout = document.getElementById(`rigourReadout`);
            if (rg && rgReadout) {
                rgReadout.textContent = rg.value;
                rg.addEventListener(`input`, function() { rgReadout.textContent = rg.value; });
            }

            // Contingency slider readout.
            const cg = document.getElementById(`contingencyInput`);
            const cgReadout = document.getElementById(`contingencyReadout`);
            if (cg && cgReadout) {
                cgReadout.textContent = cg.value;
                cg.addEventListener(`input`, function() { cgReadout.textContent = cg.value; });
            }
        }

        // Locale-aware money formatter (EUR-thousands). EN: "€38K". ES: "38 K€".
        _fmtMoneyK(k) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(k));
            return (lang === `es`) ? (n + ` K€`) : (`€` + n + `K`);
        }

        // Locale-aware percent. EN: "22.0%". ES: "22,0%".
        _fmtPct(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(1);
            return (lang === `es`) ? (s.replace(`.`, `,`) + `%`) : (s + `%`);
        }

        getChartConfig() {
            return {
                cohortChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_fit`),
                                data: [],
                                borderColor: `#2f6fb0`,
                                backgroundColor: `rgba(47,111,176,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2f6fb0`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_sat`),
                                data: [],
                                borderColor: `#b07a16`,
                                backgroundColor: `rgba(176,122,22,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#b07a16`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_margin`),
                                data: [],
                                borderColor: `#1f8a5b`,
                                backgroundColor: `rgba(31,138,91,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#1f8a5b`,
                                yAxisID: `yMargin`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#2a2336`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#7a6c8f` }, grid: { color: `rgba(43,27,77,0.08)` },
                                title: { display: true, text: this._cl(`axis_fitsat`), color: `#7a6c8f` }
                            },
                            yMargin: {
                                beginAtZero: true, max: 30, position: `right`,
                                ticks: { color: `#1f8a5b` }, grid: { drawOnChartArea: false },
                                title: { display: true, text: this._cl(`axis_marginpct`), color: `#1f8a5b` }
                            },
                            x: {
                                ticks: { color: `#7a6c8f` }, grid: { color: `rgba(43,27,77,0.06)` },
                                title: { display: true, text: this._cl(`axis_round`), color: `#7a6c8f` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.fitHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                cohortChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.fitHistory },
                        { data: ds.satHistory },
                        { data: ds.marginHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const fit = Math.round(ds.fitAvg);
            const sat = ds.satWeakest;
            const margin = ds.marginPct;
            const enrolment = ds.enrolment;
            return Math.round(
                Math.min(100, fit) * 0.35 +
                Math.min(100, sat * 20) * 0.30 +
                Math.min(100, Math.max(0, margin) / this.MARGIN_TARGET * 100) * 0.25 +
                Math.min(100, enrolment / this.FULL_SEATS * 100) * 0.10
            );
        }

        _cl(key) {
            return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fit = Math.round(ds.fitAvg);
            const sat = ds.satWeakest;
            const margin = ds.marginPct;
            const enrolment = ds.enrolment;

            const barHeld = sat >= this.SAT_BAR;
            const marginHeld = margin >= this.MARGIN_TARGET;
            const composite = this._composite(ds);

            let performanceKey = `grade_breached`;
            if (barHeld && marginHeld && composite >= 80) performanceKey = `grade_glocal`;
            else if (barHeld && marginHeld) performanceKey = `grade_both`;
            else if (barHeld && !marginHeld) performanceKey = `grade_goldplated`;
            else if (!barHeld && marginHeld) performanceKey = `grade_cheap`;
            const performance = window.mySimulation.t(performanceKey);
            const met = barHeld && marginHeld;

            const insights = [];
            if (barHeld && marginHeld) insights.push(window.mySimulation.t(`insight_both`));
            else if (!barHeld) insights.push(window.mySimulation.t(`insight_forfeit`));
            else insights.push(window.mySimulation.t(`insight_gold`));

            if (ds.forfeited) insights.push(window.mySimulation.t(`insight_forfeited`));
            if (ds.fitUae < ds.fitFr - 15) insights.push(window.mySimulation.t(`insight_uae`));
            if (ds.coreMarkets > this.CORE_CAP) insights.push(window.mySimulation.t(`insight_capacity`));
            if (enrolment >= this.FULL_SEATS) insights.push(window.mySimulation.t(`insight_enrol`));
            if (barHeld && marginHeld && composite >= 80) insights.push(window.mySimulation.t(`insight_scales`));

            return {
                fit: fit,
                satWeakest: sat,
                margin: margin,
                enrolment: enrolment,
                barHeld: barHeld,
                marginHeld: marginHeld,
                forfeited: !!ds.forfeited,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="cohort-cm-badge ` + (s.met ? `cohort-cm-met` : `cohort-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (!s.barHeld) badges.push(`<span class="cohort-cm-badge cohort-cm-fail">` + t(`cm_fail_bar`) + `</span>`);
            if (!s.marginHeld) badges.push(`<span class="cohort-cm-badge cohort-cm-fail">` + t(`cm_fail_margin`) + `</span>`);
            if (s.forfeited) badges.push(`<span class="cohort-cm-badge cohort-cm-fail">` + t(`cm_fail_forfeit`) + `</span>`);
            const kpi = (label, val) => `<div class="cohort-cm-metric"><div class="cohort-cm-metric-val">` + val + `</div><div class="cohort-cm-metric-lbl">` + label + `</div></div>`;
            const satTxt = (s.satWeakest != null) ? Number(s.satWeakest).toFixed(1) : `0.0`;
            const kpis = kpi(t(`cm_fit`), (s.fit != null ? s.fit : 0)) + kpi(t(`cm_sat`), satTxt) + kpi(t(`cm_margin`), (s.margin != null ? s.margin : 0) + `%`) + kpi(t(`cm_seats`), (s.enrolment != null ? s.enrolment : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="cohort-cm">`
                + `<div class="cohort-cm-head"><div class="cohort-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="cohort-cm-scorewrap"><span class="cohort-cm-score">` + score + `</span><span class="cohort-cm-score-max">/100</span></div>`
                + `<div class="cohort-cm-grade">` + grade + `</div>`
                + `<div class="cohort-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="cohort-cm-metrics">` + kpis + `</div>`
                + `<div class="cohort-cm-insights"><div class="cohort-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.marginPct < this.MARGIN_TARGET && state.currentPeriod >= 2) return window.mySimulation.t(`hint_margin`);
            if (ds.fitUae < 40 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_uae`);
            if (ds.coreMarkets > this.CORE_CAP) return window.mySimulation.t(`hint_capacity`);
            if (ds.satWeakest < this.SAT_BAR && state.currentPeriod >= 3) return window.mySimulation.t(`hint_bar`);
            if (ds.satWeakest >= this.SAT_BAR && ds.marginPct >= this.MARGIN_TARGET) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.fitAvg`, label: `Fit`, i18nKey: `col_fit`, formatter: (v) => Math.round(v) },
                { key: `results.satWeakest`, label: `Sat`, i18nKey: `col_sat`, formatter: (v) => Number(v).toFixed(1) },
                { key: `results.marginPct`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => this._fmtPct(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Global Cohort`,
                    subtitle:               `Novalté wants your acclaimed French flagship, “Leading Across Borders,” delivered to 90 managers as one global cohort split across France, Germany and the UAE. You must hold a 22% contribution margin (€308K) on a fixed €1.4M fee and clear a 4.2/5.0 satisfaction bar in every market. Decide what travels unchanged and what must be localized — market by market.`,
                    header_tag:             `14 April 2026 · ESCA Executive Learning · Novalté €1.4M · One cohort, three markets, one 22% margin floor`,
                    round_label:            `Round`,
                    period_of:              `of`,
                    decisions_heading:      `Your Decisions This Round`,
                    submit_btn:             `Commit the Decision`,
                    undo_btn:               `Undo Last Round`,
                    history_heading:        `Round-by-Round Record`,
                    chart_heading:          `Fit, Satisfaction & Margin Trajectory`,
                    chart_start:            `Start`,
                    coach_header:           `Facilitator (Novalté L&D head & ESCA finance director)`,
                    coach_intro:            `A program that earned its reputation delivered identically in France is not automatically a successful international one. Decide deliberately what travels unchanged, what must be localized, and how to deliver a consistent brand promise through different faculty and modes in three markets — while the economics stay intact. Standardize and you risk the 4.2 satisfaction bar; gold-plate and you blow the 22% margin floor. The art is selective, market-by-market glocalization.`,

                    fit_label:              `Cross-Cultural Fit`,
                    fit_sub:                `Avg of FR · DE · UAE (0–100)`,
                    sat_label:              `Satisfaction Outlook`,
                    sat_sub:                `Weakest market · bar ≥4.2 in each`,
                    margin_label:           `Contribution Margin`,
                    margin_sub:             `Floor 22% · €308K on a €1.4M fee`,
                    faculty_label:          `Core-Faculty Markets`,
                    faculty_sub:            `Two core faculty · max 2 markets at once`,
                    budget_label:           `Margin pool consumed by localization`,

                    clock_r1:               `Diagnose · 22% margin floor · 4.2 bar per market`,
                    clock_r2:               `Set mode & adaptation · margin pool €308K`,
                    clock_r3:               `Faculty mix · 2 core faculty · 2-market cap`,
                    clock_r4:               `Pitch & survive the pilot · lock by 1 August`,

                    round_name_r1:          `Diagnose`,
                    round_name_r2:          `Mode & Adaptation`,
                    round_name_r3:          `Faculty Mix`,
                    round_name_r4:          `Pitch & Pilot`,

                    briefing_title_r1:      `Round 1 — Diagnose the three markets`,
                    briefing_text_r1:       `The flagship earned its reputation delivered <strong>identically</strong> in France — but it has never run in three national markets at once. Your job is to separate the <strong>durable core</strong> (learning objectives, frameworks — these largely standardize) from the <strong>culture-bound surface</strong> (cases, role-plays, feedback norms, language, pacing — these often must localize). Germany expects more structure and evidence; the UAE expects relationship-building and hierarchy-sensitivity — <em>opposite moves</em>. The trap: designing one undifferentiated “international” version, or assuming a direct-feedback role-play that energizes the French cohort will land the same way in Dubai.`,
                    briefing_title_r2:      `Round 2 — Choose delivery mode & cultural-adaptation level`,
                    briefing_text_r2:       `Set, per market, the <strong>delivery mode</strong> (in-person, virtual, blended) and the <strong>cultural-adaptation level</strong> (light / moderate / deep) — each carries a cost against the €308K margin and a fit consequence. In-person lifts fit but adds travel and venue; virtual protects margin but <em>caps relationship-building, a real risk in the UAE cohort</em>; deep adaptation rewrites cases and adds local speakers. Match spend to each market's real risk: the UAE and Germany need it, France barely does. <strong>Do not gold-plate the easy market</strong> — and keep the running margin at or above 22%.`,
                    briefing_title_r3:      `Round 3 — Build the faculty mix`,
                    briefing_text_r3:       `Assemble the faculty model under genuine scarcity: <strong>two French-capable core faculty, one German affiliate, no UAE bench</strong>. Per market choose fly-in (high fit, €4,800/trip + capacity drain), recruit a local adjunct (cheap, quality risk against the 4.2 bar), or co-teach core + local (best fit, highest cost). You <em>cannot put your two core faculty in three countries the same week</em> — the trip cap is 4. Preserve brand consistency when local faculty deliver — certification, shared master materials, observation — and build a contingency for the UAE adjunct, your Round 1 risk flag.`,
                    briefing_title_r4:      `Round 4 — Pitch the design & survive the pilot`,
                    briefing_text_r4:       `The pilot module-1 scores land: <strong>France 4.5, Germany 4.3, UAE 3.9</strong> — below the 4.2 bar. Miss the bar in any one market and Novalté forfeits 10% of the fee (€140K) and the renewal. Diagnose the UAE shortfall against your Round 1 risk flags, choose a <strong>targeted, costed remediation</strong> before the remaining five modules — <em>without blowing the margin or the 1 August lock</em> — and pitch Novalté's L&D head that the program is both culturally relevant and economically sound.`,

                    r1_split_label:         `Which parts of the flagship travel unchanged, and which must be localized?`,
                    split_surface:          `Standardize the durable core (objectives, frameworks); localize the surface (cases, role-plays, feedback norms, language, pacing)`,
                    split_all:              `Localize almost everything — rebuild each market's program from scratch`,
                    split_none:             `Standardize everything — the French program earned its reputation, deliver it identically`,
                    split_core:             `Localize the core frameworks but keep the French cases and role-plays`,
                    r1_lens_label:          `How do you treat the three markets?`,
                    lens_permarket:         `Per-market — DE wants structure and evidence, UAE wants relationship and hierarchy-sensitivity: opposite moves`,
                    lens_single:            `One “international” version — a single adapted design for “abroad”`,
                    lens_french:            `No adaptation — assume what energizes the French cohort works everywhere`,
                    r1_risk_label:          `Name the single highest cross-cultural risk to the 4.2 bar.`,
                    risk_uaefeedback:       `The direct-feedback role-play in the UAE — face, hierarchy and relationship-sensitivity`,
                    risk_deabstract:        `The abstract-discussion style in Germany — which expects more structure and evidence`,
                    risk_language:          `Only the language — translate the slides and you are done`,
                    risk_norisk:            `There is no real risk — the flagship is proven`,
                    r1_rigour_label:        `How rigorously do you separate the durable core from the culture-bound surface? (%)`,
                    r1_rigour_readout:      `Diagnostic rigour:`,

                    r2_mode_fr_label:       `France — delivery mode`,
                    r2_mode_de_label:       `Germany — delivery mode`,
                    r2_mode_uae_label:      `UAE (Dubai) — delivery mode`,
                    mode_inperson:          `In-person — highest fit, venue + presence cost`,
                    mode_blended:           `Blended — solid fit at moderate cost`,
                    mode_virtual:           `Virtual-synchronous — protects margin, caps relationship-building`,
                    r2_adapt_label:         `Cultural-adaptation level (per market) — where do you spend, where do you accept “good-enough”?`,
                    adapt_fr:               `France — adaptation level`,
                    adapt_de:               `Germany — adaptation level`,
                    adapt_uae:              `UAE — adaptation level`,
                    adapt_light:            `Light (€10K)`,
                    adapt_moderate:         `Moderate (€35K)`,
                    adapt_deep:             `Deep (€70K)`,
                    r2_hint:                `Translation + local cases + guest speakers cost money against the €308K margin. Match the spend to each market's real cross-cultural risk; do not gold-plate the easy market.`,

                    r3_fac_fr_label:        `France — faculty model`,
                    r3_fac_de_label:        `Germany — faculty model`,
                    r3_fac_uae_label:       `UAE (Dubai) — faculty model`,
                    fac_core:               `Core faculty deliver — French-capable, on home turf (no trip)`,
                    fac_coteach:            `Co-teach core + local — best fit, highest cost`,
                    fac_coteach_trip:       `Co-teach core (fly-in) + certified local — best fit, 1 trip + cost`,
                    fac_affiliate:          `German-fluent affiliate, certified on the flagship — good fit, no trip`,
                    fac_flyin:              `Fly core faculty in alone — high fit, 1 trip, capacity drain`,
                    fac_local:              `Recruit a local adjunct — cheapest, quality risk`,
                    fac_local_de:           `Unvetted local adjunct — cheapest, quality risk`,
                    fac_local_uae:          `Unvetted local adjunct on price alone — cheapest, the Round 1 risk`,
                    r3_consistency_label:   `How do you keep the flagship recognizably the same when local faculty deliver?`,
                    cons_full:              `Certification + shared master materials + observation of the pilot`,
                    cons_materials:         `Shared slide deck only — hand over the materials and trust them`,
                    cons_none:              `Nothing formal — a good adjunct will figure it out`,
                    r3_contingency_label:   `Build the contingency if the UAE adjunct underperforms in the pilot? (%)`,
                    r3_contingency_readout: `Pilot-observation + backup-faculty contingency:`,

                    r4_diag_label:          `The pilot lands: FR 4.5, DE 4.3, UAE 3.9. Diagnose the UAE miss.`,
                    diag_feedback:          `Exactly the Round 1 flag — the direct-feedback role-play misfired against face and hierarchy-sensitivity`,
                    diag_language:          `Just a translation glitch — tidy the slides and re-run`,
                    diag_cohort:            `The UAE cohort simply scores harder — nothing to fix`,
                    r4_fix_label:           `Choose the targeted UAE remediation before the remaining five modules.`,
                    fix_swap:               `Swap the direct-feedback exercise for a relationship-first variant + add a certified local co-teacher (€38K)`,
                    fix_rebuild:            `Rebuild the entire UAE program from scratch and fly both core faculty out (€120K)`,
                    fix_nudge:              `A light pep-talk and minor slide edits (€6K)`,
                    fix_nothing:            `Change nothing — hope the next five modules recover the average (€0)`,
                    r4_pitch_label:         `Pitch to Novalté's L&D head: how do you frame the design?`,
                    pitch_disciplined:      `Selective glocalization — durable core held, surface localized per market, margin defended, UAE fix costed`,
                    pitch_margin:           `Lead on margin — we held 22% by standardizing hard; satisfaction is the client's problem`,
                    pitch_premium:          `Lead on quality — we rebuilt everything everywhere; do not mention the margin`,
                    r4_conviction_label:    `Conviction: how firmly do you defend that the design is BOTH culturally relevant AND economically sound? (%)`,

                    warn_rigour_range:      `Diagnostic rigour must be a percentage between 0 and 100.`,
                    warn_mode_invalid:      `Choose a valid delivery mode for each market.`,
                    warn_contingency_range: `The contingency level must be a percentage between 0 and 100.`,
                    warn_conviction_range:  `Conviction must be a percentage between 0 and 100.`,

                    coach_default:          `Decision logged.`,
                    coach_r1_surface:       `<strong>That's the mature split.</strong> Standardizing the durable core — objectives and frameworks — while localizing the culture-bound surface is glocalization, not wholesale rebuild. Now the costly localization money goes where culture actually bites: cases, role-plays, feedback norms.`,
                    coach_r1_core:          `<strong>You've localized the wrong layer.</strong> Rewriting the frameworks while keeping the French cases and role-plays inverts it — the frameworks travel, the cases and feedback style are exactly what misfires abroad. Standardize the core, localize the surface.`,
                    coach_r1_all:           `<strong>Rebuilding everything from scratch is the gold-plating instinct.</strong> Much of the flagship — its objectives and frameworks — is genuinely culture-neutral and travels unchanged. Rebuild it all and you'll devour the €308K margin on adaptations that moved nothing.`,
                    coach_r1_none:          `<strong>Identical delivery everywhere protects the margin and breaches the bar.</strong> Germany wants more structure, the UAE more relationship-sensitivity — the unaltered French design satisfies neither. A standardize-everything plan walks straight into a UAE pilot miss.`,
                    coach_r1_sharp:         `<strong>Sharp diagnosis.</strong> You separated the durable core from the culture-bound surface AND committed to designing market by market — DE for structure, UAE for relationship. That is the lens that lets one program land in three very different rooms.`,
                    coach_r1_single:        `<strong>One “international” version satisfies no one.</strong> Germany wanted more structure and evidence; the UAE wanted relationship and hierarchy-sensitivity — opposite moves. A single averaged design splits the difference and misses both. Adapt per market, not once for “abroad”.`,
                    coach_r1_french:        `<strong>Assuming France works everywhere is the core error.</strong> A successful domestic program is not automatically a successful international one. What energizes the French cohort can misfire badly in Dubai. Internationalizing is a deliberate, market-by-market choice.`,
                    coach_r1_language:      `<strong>Translation is the surface of the surface.</strong> If your only flagged risk is language, you'll ship a perfectly-translated direct-feedback exercise that still offends the UAE cohort. The risk is cultural fit, not vocabulary.`,
                    coach_r1_norisk:        `<strong>“The flagship is proven” is how the UAE pilot comes back at 3.9.</strong> It was proven in France. The whole point of this contract is that the same program must now work for three very different audiences. Name the real risk per market.`,
                    coach_r1_lowrigour:     `<strong>A loose diagnosis costs you later.</strong> If you don't rigorously separate what's durable from what's culture-bound, you'll either over-localize and lose margin or under-localize and miss the bar. The Round 1 map governs every later decision.`,

                    coach_r2_smart:         `<strong>Smart allocation.</strong> You put the deep adaptation where culture bites hardest — the UAE — rather than gold-plating France. That is matching spend to risk: it lifts the weakest market toward the 4.2 bar without wasting the margin where the program already fits.`,
                    coach_r2_misallocated:  `<strong>You gold-plated France and starved the UAE.</strong> Deep adaptation in the market that already fits, light-touch in the market most likely to breach the bar — that's spending the €308K exactly backwards. Move the money to where the cross-cultural risk actually is.`,
                    coach_r2_uaevirtual:    `<strong>Virtual delivery in the UAE caps the very thing that cohort needs.</strong> Relationship-building and presence matter most in Dubai; a screen can't carry them. You've protected a little margin and put the 4.2 bar at risk in your weakest market.`,
                    coach_r2_goldplate:     `<strong>Deep adaptation in France is mostly gold-plating.</strong> The French cohort already fits the flagship; the marginal euro there moves the satisfaction needle far less than the same euro spent in Germany or the UAE. Watch the margin floor.`,
                    coach_r2_default:       `<strong>Mode and adaptation set.</strong> Check the running margin and confirm the weakest market — the UAE — has enough mode and adaptation behind it to clear the 4.2 bar. Standardization elsewhere is what funds it.`,

                    coach_r3_consistency:   `<strong>That's how a flagship scales without diluting.</strong> Certification, shared master materials and observation let a German affiliate or a certified Dubai co-teacher deliver “Leading Across Borders” recognizably — local credibility without losing the standard that earned the reputation.`,
                    coach_r3_noconsistency: `<strong>Local faculty with no consistency mechanism dilutes the brand.</strong> Hand a different faculty member the deck and trust them, and three markets drift into three different programs. Certify them, share master materials, observe the pilot — that's the consistency spine.`,
                    coach_r3_nocontingency: `<strong>An unvetted UAE adjunct with no contingency is the 3.9 waiting to happen.</strong> You flagged this exact risk in Round 1. With no observation or backup, you only find out the adjunct underperformed when Novalté does. Build the safety net before the pilot.`,
                    coach_r3_overcommit:    `<strong>Your two core faculty cannot be in three countries the same week.</strong> France, Germany and Dubai run simultaneously in October; you've booked more core-faculty trips than two people can cover. Either the schedule breaks or someone delivers a market they were never assigned. Use the affiliate and certified locals.`,
                    coach_r3_uaecheap:      `<strong>Cheapest UAE option, no certification — exactly the Round 1 risk you flagged.</strong> An unvetted adjunct who never co-taught the flagship, with no quality mechanism, is how the pilot comes back below the bar. Certify, observe or co-teach.`,
                    coach_r3_default:       `<strong>Faculty model set.</strong> Confirm you protected the UAE with quality (certification, co-teach or contingency) and didn't over-book your two core faculty. The German affiliate and a certified Dubai co-teacher are how you cover three markets at once.`,

                    coach_r4_diag:          `<strong>Right diagnosis.</strong> The UAE 3.9 is exactly the direct-feedback risk you flagged in Round 1 — face, hierarchy and relationship-sensitivity. Now the fix is targeted and predictable, not a panicked guess. Diagnosing against your own risk map is the discipline.`,
                    coach_r4_language:      `<strong>“Just translation” misreads the miss.</strong> The UAE didn't score 3.9 because of a typo on a slide — the direct-feedback exercise misfired against face and hierarchy. Tidy the slides and you'll re-run the same offence in the next five modules.`,
                    coach_r4_cohort:        `<strong>“They just score harder” is how you forfeit €140K.</strong> Declaring the cohort un-fixable abandons the 4.2 bar in your weakest market. The Round 1 risk flag told you precisely what to change. This is the false economy the brief warns about.`,
                    coach_r4_swap:          `<strong>A targeted, costed fix — exactly right.</strong> Swapping the direct-feedback exercise for a relationship-first variant and adding a certified local co-teacher attacks the actual cause for €38K, lifting the UAE over the bar without blowing the margin or rebuilding what already worked.`,
                    coach_r4_rebuild:       `<strong>Rebuilding the whole UAE program for €120K is gold-plating the fix.</strong> Yes, satisfaction rises — but you've spent nearly half the remaining margin to repair one misfiring exercise. Which part of that €120K actually moved the needle, and which was over-engineering?`,
                    coach_r4_nudge:         `<strong>A pep-talk won't move a 3.9.</strong> Minor slide edits don't touch the direct-feedback exercise that caused the miss. The bar is contractual and the forfeit is €140K — a €6K nudge is not a remediation, it's a hope.`,
                    coach_r4_nothing:       `<strong>Changing nothing forfeits 10% of the fee.</strong> €140K — nearly half your entire €308K margin — plus the renewal, to save the cost of a targeted fix. Saving €38K to lose €140K and the client: was that the trade you meant to make?`,
                    coach_r4_pitch:         `<strong>That's a board-ready pitch.</strong> Selective glocalization, the durable core held, the surface localized per market, the margin defended and the UAE miss fixed with a costed remediation — culturally relevant AND economically sound. That's the program Novalté renews.`,
                    coach_r4_pitchmargin:   `<strong>Leading on margin while the bar is breached misreads the contract.</strong> “We held 22% by standardizing” is no defence when satisfaction — which is contractual — failed in the UAE. The forfeit makes the margin you protected disappear anyway.`,
                    coach_r4_pitchpremium:  `<strong>Leading on quality while hiding the margin invites the finance director's challenge.</strong> ESCA can't run programs below 22%. A beautiful program your own board won't fund is not a winning pitch — name both the fit and the economics.`,

                    sum_default:            `Decision made.`,
                    sum_r1_good:            `Core-vs-surface split, per-market lens, UAE risk flagged.`,
                    sum_r1_weak:            `Mis-split the program or treated the markets as one.`,
                    sum_r2_good:            `Mode & adaptation matched to each market's real risk.`,
                    sum_r2_weak:            `Gold-plated the easy market or starved the UAE.`,
                    sum_r3_good:            `Consistency-backed faculty, UAE protected, capacity held.`,
                    sum_r3_weak:            `Cheap/unvetted faculty or over-committed core capacity.`,
                    sum_r4_good:            `Right diagnosis, costed UAE fix, disciplined pitch.`,
                    sum_r4_weak:            `Mis-diagnosed, over/under-fixed, or wrong pitch frame.`,

                    insight_both:           `You held both lines: the 4.2 satisfaction bar in every market AND the 22% margin floor. That is disciplined glocalization — you standardized the durable core, localized only the culture-bound surface where it mattered, and matched faculty and mode to each market's real risk.`,
                    insight_forfeit:        `At least one market finished below the 4.2 bar. Under the contract that forfeits 10% of the fee (€140K) and the renewal — almost certainly more than you saved by under-localizing. Under-localizing is a false economy when satisfaction is contractual.`,
                    insight_gold:           `You cleared the satisfaction bar but the margin fell below the 22% floor your finance director must defend to the board. ESCA doesn't run programs there. Which adaptations actually moved the needle, and which were gold-plating you could have standardized?`,
                    insight_forfeited:      `The €140K forfeit landed — it crashed the margin you were protecting. Saving localization money to lose the fee and the renewal is exactly the trap in the brief.`,
                    insight_uae:            `The UAE finished well below France — the weakest-link market dragged your outlook. The 4.2 bar must hold in every market, so the UAE, not the average, is what governs the contract.`,
                    insight_capacity:       `You over-committed your two core faculty across three simultaneous markets. Faculty capacity is a binding constraint, not a wish — a credible local-faculty model is how you cover three rooms in the same week.`,
                    insight_enrol:          `Strong pilot health unlocked the final 15 seats — you projected the full 90-seat cohort, not just the guaranteed 75. Better per-participant economics for ESCA and Novalté both.`,
                    insight_scales:         `This design scales: standardized core, surface localized per market, faculty consistency baked in. If Novalté asks for a fourth market on the same fee, your model extends rather than breaks.`,

                    hint_margin:            `Your margin has dropped below the 22% floor. You're spending on adaptations faster than they move satisfaction. Standardize the durable core and the easy market to fund only the localization that clears the bar.`,
                    hint_uae:               `UAE fit is dangerously low — it's your weakest-link market and the 4.2 bar must hold there too. Invest mode, adaptation and quality faculty in Dubai, not in the market that already fits.`,
                    hint_capacity:          `You've booked more core-faculty trips than two people can cover. Use the certified German affiliate and a co-taught Dubai local to cover three simultaneous markets without breaking the schedule.`,
                    hint_bar:               `Your weakest market is still under the 4.2 satisfaction bar. Miss it and Novalté forfeits €140K and the renewal — target the UAE's specific cross-cultural risk now.`,
                    hint_strong:            `Strong position — both the satisfaction bar and the margin floor are holding. Lock in the faculty consistency mechanism and the costed UAE fix so the design survives the pilot.`,

                    col_round:              `Round`,
